// lib/data/characters_data.dart
class CharacterProfile {
  final String name;
  final String teluguName;
  final String title;
  final String teluguTitle;
  final String side;
  final String description;
  final String teluguDescription;
  final List<String> keyFacts;
  final List<String> teluguKeyFacts;
  final String icon;
  const CharacterProfile({required this.name, required this.teluguName, required this.title, required this.teluguTitle, required this.side, required this.description, required this.teluguDescription, required this.keyFacts, required this.teluguKeyFacts, required this.icon});
}

const List<CharacterProfile> characters = [
  CharacterProfile(name:'Krishna',teluguName:'కృష్ణుడు',title:'The Supreme God',teluguTitle:'పరమేశ్వరుడు',side:'Pandavas',description:'Krishna, the 8th avatar of Vishnu, is the central figure of the Mahabharata. He served as Arjuna\'s charioteer and delivered the Bhagavad Gita. He is Vasudeva\'s son, Devaki\'s son, raised in Gokul by Yashoda.',teluguDescription:'విష్ణువు 8వ అవతారమైన కృష్ణుడు మహాభారతంలో కేంద్ర వ్యక్తి. అర్జుని సారథిగా ఉండి భగవద్గీత ఉపదేశించాడు.',keyFacts:['Avatar of Lord Vishnu','Delivered Bhagavad Gita','Killed Kamsa','Lifted Govardhan Mountain','Had 16,108 wives'],teluguKeyFacts:['విష్ణువు అవతారం','భగవద్గీత ఉపదేశించాడు','కంసుని వధించాడు','గోవర్ధన పర్వతాన్ని ఎత్తాడు','16,108 మంది భార్యలు'],icon:'🦚'),
  CharacterProfile(name:'Arjuna',teluguName:'అర్జుని',title:'The Greatest Archer',teluguTitle:'మహాధనుర్ధారి',side:'Pandavas',description:'Arjuna, the third Pandava and son of Indra, is considered the greatest archer of all time. His bow is the Gandiva. He is also known as Partha, Vijaya, Dhananjaya, Savyasachi, Gudakesha.',teluguDescription:'పాండవులలో మూడవ వాడు, ఇంద్రుని పుత్రుడు అర్జుని అన్నికాలాల గొప్ప విలుకాడు. అతని విల్లు గాండీవం. పార్థ, విజయ, ధనంజయ అని పేర్లు.',keyFacts:['Son of Indra','Wielded the divine bow Gandiva','Received Pashupatastra from Shiva','Recipient of Bhagavad Gita','Killed Karna, Jayadratha'],teluguKeyFacts:['ఇంద్రుని పుత్రుడు','గాండీవ విల్లు ధరించాడు','శివుని నుండి పాశుపతాస్త్రం పొందాడు','భగవద్గీత పొందాడు','కర్ణ జయద్రథులను వధించాడు'],icon:'🏹'),
  CharacterProfile(name:'Yudhishthira',teluguName:'యుధిష్ఠిరుడు',title:'The Dharma King',teluguTitle:'ధర్మరాజు',side:'Pandavas',description:'Yudhishthira, the eldest Pandava and son of Yama (god of Dharma), was known for his adherence to truth and dharma. His weakness was gambling. He answered the Yaksha\'s questions and saved his brothers.',teluguDescription:'పాండవులలో పెద్దవాడు, యముని పుత్రుడు. ధర్మం తప్పనివాడు. జూదమే అతని బలహీనత. యక్షుని ప్రశ్నలకు సమాధానం చెప్పి తమ్ముళ్ళను రక్షించాడు.',keyFacts:['Son of Yama, god of Dharma','Never told a lie (once partially)','Lost kingdom in dice game','Answered Yaksha\'s questions','Reached heaven with his body'],teluguKeyFacts:['ధర్మదేవుని పుత్రుడు','అసత్యం పలికేవాడు కాదు','జూదంలో రాజ్యం పోగొట్టాడు','యక్ష ప్రశ్నలకు సమాధానం చెప్పాడు','శరీరంతో స్వర్గానికి వెళ్ళాడు'],icon:'⚖️'),
  CharacterProfile(name:'Bhima',teluguName:'భీముడు',title:'The Mighty Warrior',teluguTitle:'మహాబలుడు',side:'Pandavas',description:'Bhima, the second Pandava and son of Vayu, was the strongest warrior. He killed all 100 Kauravas as he vowed. He killed Jarasandha, Bakasura, Kichaka, Hidimba. His weapon was the mace (gada).',teluguDescription:'వాయుపుత్రుడు భీముడు బలవంతుడు. 100 మంది కౌరవులను ప్రతిజ్ఞ చేసినట్లు చంపాడు. జరాసంధ బకాసుర కీచక హిడింబులను వధించాడు.',keyFacts:['Son of Vayu','Killed all 100 Kauravas','Strongest warrior of his time','Ate entire forest fruits in Vanasavam','Broke Duryodhana\'s thighs'],teluguKeyFacts:['వాయుపుత్రుడు','100 కౌరవులను చంపాడు','కాలంలో బలవంతమైన యోధుడు','వనవాసంలో అడవి పళ్ళు తినేవాడు','దుర్యోధనుని తొడలు విరిచాడు'],icon:'💪'),
  CharacterProfile(name:'Nakula',teluguName:'నకులుడు',title:'The Handsome Warrior',teluguTitle:'అందమైన యోధుడు',side:'Pandavas',description:'Nakula, fourth Pandava and son of Ashvins, was the most handsome man of his time. He was an expert in horse management (Ashvaveda). Sahadeva was his twin brother.',teluguDescription:'నాలుగవ పాండవుడు, అశ్వినీ దేవతల పుత్రుడు. కాలంలో అందమైన వ్యక్తి. అశ్వ శాస్త్రంలో నిపుణుడు. సహదేవుడు అతని జంట సోదరుడు.',keyFacts:['Son of Ashvini Kumaras','Most handsome man','Expert in horse management','Defeated many kings in Ashvamedha','Fought bravely in Kurukshetra'],teluguKeyFacts:['అశ్వినీ కుమారుల పుత్రుడు','అందమైన వ్యక్తి','అశ్వ శాస్త్ర నిపుణుడు','అశ్వమేధలో అనేక రాజులను ఓడించాడు','కురుక్షేత్రంలో వీరత్వం చూపాడు'],icon:'🐴'),
  CharacterProfile(name:'Sahadeva',teluguName:'సహదేవుడు',title:'The Wise Astrologer',teluguTitle:'జ్ఞాని జ్యోతిష్కుడు',side:'Pandavas',description:'Sahadeva, fifth Pandava and twin of Nakula, was the wisest of the Pandavas and an astrologer. He knew the future but was cursed not to reveal it unless asked. He killed Shakuni.',teluguDescription:'ఐదవ పాండవుడు, నకులుని జంట. పాండవులలో జ్ఞాని, జ్యోతిష్కుడు. భవిష్యత్తు తెలుసు కానీ అడగకుండా చెప్పవద్దని శాపం. శకుని వధ చేసాడు.',keyFacts:['Son of Ashvini Kumaras','Expert astrologer','Killed Shakuni','Knew the future','Wisest of the Pandavas'],teluguKeyFacts:['అశ్వినీ కుమారుల పుత్రుడు','జ్యోతిష్క నిపుణుడు','శకుని వధ చేసాడు','భవిష్యత్తు తెలుసు','పాండవులలో జ్ఞాని'],icon:'🌟'),
  CharacterProfile(name:'Draupadi',teluguName:'ద్రౌపది',title:'The Fire-born Princess',teluguTitle:'అగ్నిసుత',side:'Pandavas',description:'Draupadi (Panchali) was born from a sacrificial fire. She was the common wife of all five Pandavas. Her humiliation in the Kaurava court led to the Mahabharata war. She was fiercely intelligent and spirited.',teluguDescription:'ద్రౌపది యజ్ఞాగ్ని నుండి జన్మించింది. ఐదుగురు పాండవులకు పత్ని. సభలో ఆమెను అవమానించడం మహాభారత యుద్ధానికి దారితీసింది.',keyFacts:['Born from sacrificial fire','Wife of all 5 Pandavas','Her humiliation caused the war','Was a devoted and spirited woman','Shared 5 years with each husband'],teluguKeyFacts:['యజ్ఞాగ్ని నుండి జన్మించింది','5 మంది పాండవులకు భార్య','ఆమె అవమానం యుద్ధానికి కారణం','భక్తిగల, వీరత్వపు మహిళ','ప్రతి భర్తతో 5 సంవత్సరాలు'],icon:'🔥'),
  CharacterProfile(name:'Duryodhana',teluguName:'దుర్యోధనుడు',title:'The Crown Prince',teluguTitle:'యువరాజు',side:'Kauravas',description:'Duryodhana, eldest of the 100 Kauravas and son of Dhritarashtra, was the primary antagonist. His jealousy of the Pandavas drove the Mahabharata story. Yet he was a brave warrior who never showed his back to enemies.',teluguDescription:'ధృతరాష్ట్రుని పెద్ద పుత్రుడు, 100 కౌరవులలో జ్యేష్ఠుడు. పాండవులపై అసూయే మహాభారతానికి కారణం. ఆత్మాభిమానం కల యోధుడు.',keyFacts:['Eldest of 100 Kauravas','Never showed back to enemies','Close friend of Karna','Refused peace at any cost','Died with dignity fighting Bhima'],teluguKeyFacts:['100 కౌరవులలో పెద్దవాడు','శత్రువుకు వీపు చూపించలేదు','కర్ణుడు ఆప్త మిత్రుడు','శాంతిని తిరస్కరించాడు','భీముడితో పోరాడి గర్వంగా మరణించాడు'],icon:'👑'),
  CharacterProfile(name:'Karna',teluguName:'కర్ణుడు',title:'The Tragic Hero',teluguTitle:'విషాద వీరుడు',side:'Kauravas',description:'Karna (Radheya) was actually the eldest Pandava, son of Kunti and Surya, abandoned at birth. He became the greatest rival of Arjuna. He was known for his unmatched generosity — he gave away his kavach and kundala to Indra.',teluguDescription:'కర్ణుడు వాస్తవానికి కుంతీపుత్రుడు, సూర్యుని పుత్రుడు, పాండవులలో జ్యేష్ఠుడు. జన్మతోనే కవచ కుండలాలు కలవాడు. దాన వీరుడు.',keyFacts:['Biological son of Kunti and Surya','Had natural Kavacha and Kundala','Gave away Kavacha-Kundala to Indra','Greatest rival of Arjuna','Died unarmed while lifting chariot wheel'],teluguKeyFacts:['కుంతి సూర్యులకు జన్మించాడు','జన్మతో కవచ కుండలాలు కలవాడు','ఇంద్రునికి కవచ కుండలాలు దానం చేసాడు','అర్జుని సమకాలీన శ్రేష్ఠ యోధుడు','రథ చక్రం ఎత్తుతుండగా నిరాయుధంగా మరణించాడు'],icon:'☀️'),
  CharacterProfile(name:'Bhishma',teluguName:'భీష్ముడు',title:'The Grandsire',teluguTitle:'పితామహుడు',side:'Kauravas',description:'Bhishma (Devavrata) was the grandsire of both Pandavas and Kauravas. He took the terrible oath of celibacy and was blessed with iccha mrityu (death at will). He fought for Kauravas against his own wishes.',teluguDescription:'భీష్ముడు పాండవ కౌరవ రెండు పక్షాలకు పితామహుడు. బ్రహ్మచర్య ప్రతిజ్ఞ చేసి ఇచ్ఛా మరణ వరం పొందాడు. తన ఇష్టం లేకున్నా కౌరవుల తరపున పోరాడాడు.',keyFacts:['Son of Ganga and Shantanu','Took terrible oath of celibacy','Had the boon of choosing time of death','Commander for 10 days','Gave wisdom on deathbed (Anushasana Parva)'],teluguKeyFacts:['గంగ శంతనుల పుత్రుడు','భీష్మ ప్రతిజ్ఞ చేసాడు','ఇచ్ఛా మరణ వరం కలవాడు','10 రోజులు సేనాపతి','శయ్యపై అనుశాసన పర్వంలో జ్ఞానం చెప్పాడు'],icon:'🏔️'),
  CharacterProfile(name:'Drona',teluguName:'ద్రోణుడు',title:'The Royal Teacher',teluguTitle:'రాజగురువు',side:'Kauravas',description:'Dronacharya was the royal teacher (guru) of both Pandavas and Kauravas. He taught Arjuna archery. He asked Ekalavya for his thumb as gurudakshina. He was killed by deception after hearing Ashwatthama died.',teluguDescription:'ద్రోణాచార్యుడు పాండవ కౌరవులకు రాజగురువు. ఏకలవ్యుని బొటన వేలు గురుదక్షిణగా తీసుకున్నాడు. అశ్వత్థామ మరణించాడని విని నిరాయుధుడై మరణించాడు.',keyFacts:['Royal teacher of Pandavas and Kauravas','Arjuna was his favorite student','Demanded Ekalavya\'s thumb','Commander for 5 days','Died deceived by Ashwatthama\'s news'],teluguKeyFacts:['పాండవ కౌరవులకు రాజగురువు','అర్జుని అతనికి ప్రియ శిష్యుడు','ఏకలవ్యుని బొటన వేలు తీసుకున్నాడు','5 రోజులు సేనాపతి','మోసంతో మరణించాడు'],icon:'🎯'),
  CharacterProfile(name:'Shakuni',teluguName:'శకుని',title:'The Master Schemer',teluguTitle:'కుట్ర మాస్టర్',side:'Kauravas',description:'Shakuni, the uncle of Duryodhana, was the mastermind behind the Mahabharata tragedy. His dice were made from his father\'s bones and always obeyed him. He was killed by Sahadeva.',teluguDescription:'దుర్యోధనుని మేనమామ శకుని మహాభారత విషాదానికి సూత్రధారి. అతని పాచికలు తండ్రి ఎముకలతో చేయబడ్డాయి. సహదేవుని చేతిలో మరణించాడు.',keyFacts:['Uncle of Duryodhana','Made dice from his father\'s bones','Mastermind of the dice game','Symbol of deceit','Killed by Sahadeva'],teluguKeyFacts:['దుర్యోధనుని మేనమామ','తండ్రి ఎముకలతో పాచికలు','జూద క్రీడ సూత్రధారి','మోసానికి చిహ్నం','సహదేవుని చేతిలో మరణించాడు'],icon:'🎲'),
  CharacterProfile(name:'Abhimanyu',teluguName:'అభిమన్యుడు',title:'The Brave Youth',teluguTitle:'వీర యువకుడు',side:'Pandavas',description:'Abhimanyu, son of Arjuna and Subhadra, learned the technique of entering Chakravyuha while still in the womb. But he did not learn how to exit it. He was killed treacherously by multiple warriors.',teluguDescription:'అర్జుని సుభద్రల పుత్రుడు అభిమన్యుడు గర్భంలో ఉండగా చక్రవ్యూహ ప్రవేశం నేర్చుకున్నాడు. నిష్క్రమణ తెలియక 7 మంది మహాయోధులచే వీరమరణం పొందాడు.',keyFacts:['Son of Arjuna and Subhadra','Learned Chakravyuha in womb','Did not know how to exit','Killed by 7 warriors treacherously','His death enraged Arjuna'],teluguKeyFacts:['అర్జుని సుభద్రల పుత్రుడు','గర్భంలో చక్రవ్యూహ ప్రవేశం నేర్చుకున్నాడు','నిష్క్రమణ తెలియదు','7 మంది యోధులు మోసంతో చంపారు','అతని మరణం అర్జుని ఆగ్రహాన్ని రగిలించింది'],icon:'⚡'),
  CharacterProfile(name:'Kunti',teluguName:'కుంతి',title:'The Noble Mother',teluguTitle:'మహానోబల్ తల్లి',side:'Pandavas',description:'Kunti was the mother of Yudhishthira, Bhima, and Arjuna. She had a secret son Karna from Surya before her marriage. She kept this secret her entire life. She was also the foster mother of Madri\'s sons.',teluguDescription:'యుధిష్ఠిర భీమ అర్జునుల తల్లి కుంతి. వివాహానికి ముందు సూర్యుని వల్ల కర్ణుడు జన్మించాడు. ఈ రహస్యం జీవితాంతం దాచుకుంది.',keyFacts:['Mother of 3 Pandavas','Secretly bore Karna from Surya','Was given a mantra by sage Durvasa','Asked Karna to spare 4 Pandavas','Lived in forest after the war'],teluguKeyFacts:['3 మంది పాండవుల తల్లి','సూర్యుని వల్ల రహస్యంగా కర్ణుని కన్నది','దుర్వాస మంత్రం పొందింది','4 పాండవులను వదిలిపెట్టమని కర్ణుని కోరింది','యుద్ధం తర్వాత అడవిలో నివసించింది'],icon:'👸'),
  CharacterProfile(name:'Gandhari',teluguName:'గాంధారి',title:'The Devoted Wife',teluguTitle:'సచ్చీలవతి భార్య',side:'Kauravas',description:'Gandhari, queen of Hastinapura and mother of 100 Kauravas, blindfolded herself for life when she learned her husband was blind. Her unwavering devotion gave Duryodhana a diamond-like body when she looked at him.',teluguDescription:'హస్తినాపుర రాణి, 100 కౌరవుల తల్లి గాంధారి భర్త గుడ్డివాడని తెలిసి జీవితాంతం కళ్ళకు గుడ్డ కట్టుకుంది. ఆమె దర్శనం వల్ల దుర్యోధనుని శరీరం వజ్రంలా మారింది.',keyFacts:['Voluntarily wore blindfold','Mother of 100 Kauravas','Her gaze could have made Duryodhana invincible','Cursed Krishna after the war','Symbol of devoted but tragic motherhood'],teluguKeyFacts:['స్వచ్ఛందంగా కళ్ళకు గుడ్డ కట్టుకుంది','100 కౌరవుల తల్లి','ఆమె చూపు దుర్యోధనుని అజేయుని చేసేది','యుద్ధం తర్వాత కృష్ణుని శపించింది','భక్తిగల కానీ విషాద మాతృత్వానికి చిహ్నం'],icon:'🙏'),
  CharacterProfile(name:'Vidura',teluguName:'విదురుడు',title:'The Wisest Minister',teluguTitle:'జ్ఞాని మంత్రి',side:'Neutral',description:'Vidura, the wise prime minister of Hastinapura, was the incarnation of Yama. He always gave righteous counsel. He warned the Pandavas about the lacquer house and always spoke the truth regardless of consequences.',teluguDescription:'హస్తినాపుర మహామంత్రి విదురుడు యమధర్మరాజు అవతారం. ధర్మాన్ని మాత్రమే చెప్పేవాడు. లక్క ఇంటి విషయంలో పాండవులను హెచ్చరించాడు.',keyFacts:['Incarnation of Yama','Always gave righteous counsel','Warned Pandavas of lacquer house','Never compromised on truth','Walked into forest to meet Krishna'],teluguKeyFacts:['యమధర్మరాజు అవతారం','ధర్మ బోధ మాత్రమే చేసేవాడు','లక్క ఇంటి విషయంలో హెచ్చరించాడు','సత్యాన్ని వదలలేదు','కృష్ణుని కలవడానికి అడవిలోకి వెళ్ళాడు'],icon:'📜'),
];
